	azimuth FLOAT NOT NULL, 
	inverter_kw FLOAT, 
	battery_kwh FLOAT DEFAULT '0', 
	supplier VARCHAR(100), 
	customer_type VARCHAR(30) DEFAULT 'individual' NOT NULL, 
	compensation_type VARCHAR(30) DEFAULT 'quantity' NOT NULL, 
	price_lei_kwh FLOAT, 
	monthly_kwh FLOAT, 
	carryover_kwh FLOAT DEFAULT '0', 
	pvgis_annual_kwh FLOAT, 
	pvgis_monthly_json JSON, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS subscriptions (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	stripe_session_id VARCHAR(255), 
	status VARCHAR(30), 
	current_period_end TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS bills (
	id SERIAL NOT NULL, 
